@@ -0,0 +1,111 @@
+import {createChatOrchestrator} from './chatOrchestrator.js';
+import type {AIProvider, MessageChunk} from '../types/ai.js';
+import type {ChatSession} from '../types/session.js';
+import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
+
+const SENT_AT = '2026-01-01T00:00:00.000Z';
+
+function createSession(content: string): ChatSession {
+  return {
+    sessionId: 's1',
+    userId: 'u1',
+    entries: [{role: 'user', content, timestamp: SENT_AT}],
+  };
+}
+
+function createRejectingProvider(reason: unknown): AIProvider {
+  return {
+    // eslint-disable-next-line require-yield
+    async *sendMessage(): AsyncGenerator<MessageChunk> {
+      throw reason;
+    },
+    async generateStructured<T>(): Promise<T> {
+      return {} as T;
+    },
+  };
+}
+
+const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
+
+describe('ChatOrchestrator onError', () => {
+  it('calls onError once with an Error whose cause is a thrown string, and rejects to the caller unchanged', async () => {
+    let capturedError: Error | undefined;
+    let callCount = 0;
+    const hooks = {
+      onError: async (_session: ChatSession, error: Error) => {
+        capturedError = error;
+        callCount++;
+      },
+    };
+
+    const orchestrator = createChatOrchestrator(createRejectingProvider('string rejection'), promptBuilder, undefined, {
+      hooks,
+    });
+
+    let caughtRejection: unknown;
+    try {
+      await orchestrator.processMessage(createSession('hello'));
+    } catch (e) {
+      caughtRejection = e;
+    }
+
+    expect(caughtRejection).toBe('string rejection');
+    expect(callCount).toBe(1);
+    expect(capturedError).toBeInstanceOf(Error);
+    expect(capturedError?.cause).toBe('string rejection');
+  });
+
+  it('calls onError once with an Error whose cause is a thrown plain object, and rejects to the caller unchanged', async () => {
+    let capturedError: Error | undefined;
+    let callCount = 0;
+    const hooks = {
+      onError: async (_session: ChatSession, error: Error) => {
+        capturedError = error;
+        callCount++;
+      },
+    };
+
+    const obj = {custom: 'error shape'};
+    const orchestrator = createChatOrchestrator(createRejectingProvider(obj), promptBuilder, undefined, {hooks});
+
+    let caughtRejection: unknown;
+    try {
+      await orchestrator.processMessage(createSession('hello'));
+    } catch (e) {
+      caughtRejection = e;
+    }
+
+    expect(caughtRejection).toBe(obj);
+    expect(callCount).toBe(1);
+    expect(capturedError).toBeInstanceOf(Error);
+    expect(capturedError?.cause).toBe(obj);
+  });
+
+  it('calls onError once with an Error whose cause is thrown undefined, and rejects to the caller unchanged', async () => {
+    let capturedError: Error | undefined;
+    let callCount = 0;
+    const hooks = {
+      onError: async (_session: ChatSession, error: Error) => {
+        capturedError = error;
+        callCount++;
+      },
+    };
+
+    const orchestrator = createChatOrchestrator(createRejectingProvider(undefined), promptBuilder, undefined, {hooks});
+
+    let caughtRejection: unknown;
+    let didThrow = false;
+    try {
+      await orchestrator.processMessage(createSession('hello'));
+    } catch (e) {
+      caughtRejection = e;
+      didThrow = true;
+    }
+
+    expect(didThrow).toBe(true);
+    expect(caughtRejection).toBeUndefined();
+    expect(callCount).toBe(1);
+    expect(capturedError).toBeInstanceOf(Error);
+    expect(capturedError?.cause).toBeUndefined();
+  });
+});
